import math
from itertools import permutations

def is_square(k):
    if k < 1:
        return False
    root = int(math.isqrt(k))
    return root * root == k

def is_cool_backtracking(n):
    # Backtracking function to find a permutation
    def solve(current_sum, used, path):
        if len(path) == n:
            return path

        # Try all unused numbers
        for next_num in range(1, n + 1):
            if next_num not in used:
                next_sum = current_sum + next_num

                # Check the condition: next_sum must NOT be a perfect square
                if not is_square(next_sum):
                    used.add(next_num)
                    path.append(next_num)

                    # Recurse
                    result = solve(next_sum, used, path)

                    if result:
                        return result

                    # Backtrack
                    path.pop()
                    used.remove(next_num)

        return None

    # Start the search
    initial_used = set()
    initial_path = []
    permutation = solve(0, initial_used, initial_path)

    if permutation:
        return True, permutation
    else:
        return False, None

