import itertools
import math

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def is_cool(N):
    elements = list(range(1, N + 1))

    # Iterate through all permutations
    for perm in itertools.permutations(elements):
        prefix_sum = 0
        is_valid_perm = True
        for i in range(N):
            prefix_sum += perm[i]
            if is_square(prefix_sum):
                is_valid_perm = False
                break

        if is_valid_perm:
            # Found a cool permutation
            return True

    # No permutation worked
    return False

N_values = [13, 14, 15]
results = {}
for N in N_values:
    print(f"Checking N={N}: {is_cool(N)}")

# For completeness, checking a small edge case previously discussed
print(f"Checking N=1: {is_cool(1)}")
print(f"Checking N=8: {is_cool(8)}")
